const SchwingerHistogram& schwinger_histogram_model(const std::string&id,bool square){
if(id=="L4E2G15")return square?histogram_L4E2G15_weighted_square:histogram_L4E2G15_weighted_linear;
if(id=="L4E2G19")return square?histogram_L4E2G19_weighted_square:histogram_L4E2G19_weighted_linear;
if(id=="L4E2G21")return square?histogram_L4E2G21_weighted_square:histogram_L4E2G21_weighted_linear;
if(id=="L4E2G46")return square?histogram_L4E2G46_weighted_square:histogram_L4E2G46_weighted_linear;
if(id=="L4E2G6")return square?histogram_L4E2G6_weighted_square:histogram_L4E2G6_weighted_linear;
throw std::invalid_argument("untrained common-domain graph");}

SchwingerMappedPoint schwinger_histogram_map(const std::string&id,bool square,const std::array<Real,7>&p){
 const auto&model=schwinger_histogram_model(id,square);SchwingerMappedPoint result;result.jacobian=1;
 for(long axis=0;axis<7;++axis){long cumulative=0;bool found=false;
  for(long bin=0;bin<long(model.bins);++bin){long mass=model.counts[axis][bin];Real upper=Real(cumulative+mass)/65536;
   if(arb_lt(p[axis].v,upper.v)){Real slope=Real(65536)/Real(long(model.bins)*mass);result.point[axis]=Real(bin)/Real(long(model.bins))+(p[axis]-Real(cumulative)/65536)*slope;result.jacobian=result.jacobian*slope;found=true;break;}
   Real distance=p[axis]-upper;if(!arb_is_nonnegative(distance.v))throw std::runtime_error("uncertain histogram cell requires higher precision");cumulative+=mass;
  }
  if(!found)throw std::invalid_argument("strict histogram cube required");pos(result.point[axis],"positive mapped coordinate");pos(1-result.point[axis],"mapped coordinate below one");
 }
 pos(result.jacobian,"positive complete histogram Jacobian");return result;
}
Real schwinger_histogram_value(const Graph&g,bool positive,bool square,const std::array<Real,7>&p){
 auto mapped=schwinger_histogram_map(g.id,square,p);return mapped.jacobian*value(g,positive,square,mapped.point);
}

